    passwordHash: await hashPassword(input.password),
  });

  const org = await createOrganization(user.id, {
    name: workspaceName(input.name),
    slug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * `<display name>'s workspace`, with the display name shortened (by code
 * point) until the whole name fits the workspace schema's limit.
 */
export function workspaceName(displayName: string): string {
  const max = createOrganizationSchema.shape.name.maxLength ?? 64;
  const chars = Array.from(displayName);
  const room = Math.max(0, max - WORKSPACE_SUFFIX.length);
  return `${chars.slice(0, room).join("")}${WORKSPACE_SUFFIX}`;
}

/**
 * Derives the first workspace's slug from the display name. Never refuses:
 * reserved and taken slugs are suffixed by `uniqueSlug()`, and a slug too
 * short to be valid falls back to `workspace` (itself suffixed when taken).
 */
async function deriveWorkspaceSlug(displayName: string): Promise<string> {
  const derived = slugify(displayName);
  const base =
    derived.length >= SLUG_MIN_LENGTH ? derived : FALLBACK_WORKSPACE_SLUG;
  const taken = await orgRepo.listTakenOrgSlugs(base);
  return uniqueSlug(base, taken);
}

